<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;use App\Core\Auth;
final class StockController{public function index():void{Auth::requireRole(['administrator','librarian']);$db=Database::connection();$db->exec('CREATE TABLE IF NOT EXISTS stock_checks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,expected_quantity INT UNSIGNED NOT NULL,counted_quantity INT UNSIGNED NOT NULL,difference INT NOT NULL,checked_by INT UNSIGNED NOT NULL,checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,notes TEXT,CONSTRAINT fk_stock_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE,CONSTRAINT fk_stock_user FOREIGN KEY(checked_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB');$rows=$db->query('SELECT s.*,b.title,u.name checked_by_name FROM stock_checks s JOIN books b ON b.id=s.book_id JOIN users u ON u.id=s.checked_by ORDER BY s.checked_at DESC')->fetchAll();$title='Stock Verification';require BASE_PATH.'/app/Views/stock/index.php';}public function create():void{Auth::requireRole(['administrator','librarian']);$db=Database::connection();$books=$db->query('SELECT id,title,quantity FROM books ORDER BY title')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$book=(int)$_POST['book_id'];$s=$db->prepare('SELECT quantity FROM books WHERE id=?');$s->execute([$book]);$expected=(int)$s->fetchColumn();$counted=max(0,(int)$_POST['counted_quantity']);$db->prepare('INSERT INTO stock_checks(book_id,expected_quantity,counted_quantity,difference,checked_by,notes) VALUES(?,?,?,?,?,?)')->execute([$book,$expected,$counted,$counted-$expected,Auth::user()['id'],trim($_POST['notes']??'')]);$db->prepare('UPDATE books SET quantity=?,available_quantity=LEAST(available_quantity+?,?) WHERE id=?')->execute([$counted,$counted-$expected,$counted,$book]);Security::flash('success','Stock verification saved and inventory updated.');Security::redirect('stock');}$title='Verify Stock';require BASE_PATH.'/app/Views/stock/form.php';}public function delete():void{Auth::requireRole(['administrator','librarian']);if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('stock');}$s=Database::connection()->prepare('DELETE FROM stock_checks WHERE id=?');$s->execute([(int)($_POST['id']??0)]);Security::flash('success',$s->rowCount()?'Stock verification record deleted.':'Stock verification record not found.');Security::redirect('stock');}}
